<section class="admin-panel"><h2 class="admin-panel-title">Tạo đơn nhập hàng nhiều dòng</h2><form method="post" action="<?= BASE_URL ?>admin/procurement/order"><div class="admin-field"><label>Nhà cung cấp *</label><select name="supplier_id" required><?php foreach($suppliers as $s):?><option value="<?= (int)$s['id'] ?>"><?= adminE($s['supplier_code'].' — '.$s['name']) ?></option><?php endforeach;?></select></div><?php for($line=0;$line<4;$line++):?><fieldset style="border:1px solid #ddd;padding:.75rem;margin:.75rem 0"><legend>Dòng hàng <?= $line+1 ?><?= $line===0?' *':' (tùy chọn)' ?></legend><div class="admin-field"><label>Biến thể</label><select name="variant_id[]" <?= $line===0?'required':'' ?>><option value="">-- Chọn biến thể --</option><?php foreach($variants as $v):?><option value="<?= (int)$v['id'] ?>"><?= adminE(($v['sku']?:'#'.$v['id']).' — '.$v['product_name'].' / '.$v['size'].' / '.$v['color']) ?></option><?php endforeach;?></select></div><div class="admin-grid"><div class="admin-field"><label>Số lượng</label><input name="quantity[]" type="number" min="1" <?= $line===0?'required':'' ?>></div><div class="admin-field"><label>Đơn giá vốn</label><input name="unit_cost[]" type="number" min="1" step="1000" <?= $line===0?'required':'' ?>></div><div class="admin-field"><label>VAT đầu vào (%)</label><input name="tax_rate[]" type="number" min="0" max="100" step="0.01" value="8"></div></div></fieldset><?php endfor;?><div class="admin-field"><label>Ngày dự kiến</label><input name="expected_at" type="date"></div><div class="admin-field"><label>Ghi chú</label><textarea name="note"></textarea></div><button class="admin-btn primary">Tạo đơn nhập</button></form></section></div>
<section class="admin-panel"><h2 class="admin-panel-title">Đơn nhập hàng</h2><?php foreach($orders as $o):?><article style="border-bottom:1px solid #ddd;padding:1rem 0"><p><strong><?= adminE($o['po_code']) ?></strong> · <?= adminE($o['supplier_name']) ?> · <?= adminMoney($o['total_amount']) ?> · Trạng thái: <?= adminE($o['status']) ?> · Công nợ: <?= adminE($o['payable_status']??'Chưa phát sinh') ?></p><div class="admin-table-wrapper"><table class="admin-table"><thead><tr><th>Dòng hàng</th><th>Đặt</th><th>Đã nhận</th><th>Còn lại</th><?php if(in_array($o['status'],['ordered','partially_received'],true)):?><th>Nhận lần này</th><?php endif;?></tr></thead><tbody><?php foreach(($items_by_order[(int)$o['id']]??[]) as $item):$remaining=max(0,(int)$item['quantity_ordered']-(int)$item['quantity_received']);?><tr><td><?= adminE(($item['sku']?:'#'.$item['variant_id']).' — '.$item['product_name'].' / '.$item['size'].' / '.$item['color']) ?></td><td><?= (int)$item['quantity_ordered'] ?></td><td><?= (int)$item['quantity_received'] ?></td><td><?= $remaining ?></td><?php if(in_array($o['status'],['ordered','partially_received'],true)):?><td><input form="receive-<?= (int)$o['id'] ?>" name="receive_qty[<?= (int)$item['id'] ?>]" type="number" min="0" max="<?= $remaining ?>" value="0" style="max-width:100px"></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php if(in_array($o['status'],['ordered','partially_received'],true)):?><form id="receive-<?= (int)$o['id'] ?>" method="post" action="<?= BASE_URL ?>admin/procurement/receive" onsubmit="return confirm('Xác nhận đúng số lượng thực nhận?')"><input type="hidden" name="id" value="<?= (int)$o['id'] ?>"><button class="admin-btn-sm admin-btn primary">Ghi nhận lần nhận hàng</button></form><?php endif;?></article><?php endforeach;?></section>
<section class="admin-panel"><h2 class="admin-panel-title">Công nợ nhà cung cấp</h2><div class="admin-table-wrapper"><table class="admin-table"><thead><tr><th>Nhà cung cấp</th><th>Đơn</th><th>Phải trả</th><th>Đã trả</th><th>Hạn</th><th>Trạng thái</th><th>Thanh toán</th></tr></thead><tbody><?php foreach($payables as $p):?><tr><td><?= adminE($p['supplier_name']) ?></td><td><?= adminE($p['po_code']) ?></td><td><?= adminMoney($p['amount_due']) ?></td><td><?= adminMoney($p['amount_paid']) ?></td><td><?= adminE($p['due_date']) ?></td><td><?= adminE($p['status']) ?></td><td><?php if(!in_array($p['status'],['paid','void'],true)):?><form method="post" action="<?= BASE_URL ?>admin/procurement/pay" style="display:flex;gap:.4rem"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><input name="amount" type="number" min="1" step="1000" required placeholder="Số tiền"><input name="reference" required placeholder="Mã giao dịch"><button class="admin-btn-sm admin-btn primary">Ghi nhận</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="admin-panel"><h2 class="admin-panel-title">Lịch sử thanh toán công nợ</h2><div class="admin-table-wrapper"><table class="admin-table"><thead><tr><th>Thời gian</th><th>Nhà cung cấp</th><th>Đơn nhập</th><th>Số tiền</th><th>Mã tham chiếu</th></tr></thead><tbody><?php foreach($supplier_payments as $payment):?><tr><td><?= adminE($payment['paid_at']) ?></td><td><?= adminE($payment['supplier_name']) ?></td><td><?= adminE($payment['po_code']) ?></td><td><?= adminMoney($payment['amount']) ?></td><td><?= adminE($payment['reference']) ?></td></tr><?php endforeach;?><?php if(!$supplier_payments):?><tr><td colspan="5">Chưa có lần thanh toán nào.</td></tr><?php endif;?></tbody></table></div></section>
